/**
 * CrosshairProvider - 跨图联动十字光标。
 *
 * 设计要点:
 *   - 用 ref 存状态,不走 React state,避免每次鼠标移动都重渲染
 *   - 订阅者直接在 useEffect 内拿到 ref 当前值 + 监听变化
 *   - 鼠标 1000 次/秒移动,React 重渲染次数 = 0
 *
 * 使用模式:
 *   const crosshair = useCrosshair();
 *   useEffect(() => {
 *     const unsub = crosshair.subscribe((state) => {
 *       // 直接操作 canvas / DOM,不走 React state
 *       canvasRef.current.style.setProperty('--crosshair-x', String(state.time));
 *     });
 *     return unsub;
 *   }, []);
 */
'use client';

import { createContext, useContext, useMemo, useRef, type ReactNode } from 'react';
import type { CrosshairProtocol, CrosshairState, Unsubscribe } from '../protocols';

const CrosshairContext = createContext<CrosshairProtocol | null>(null);

const INITIAL_STATE: CrosshairState = {
  symbol: null,
  time: null,
  value: null,
  source: null,
};

interface CrosshairProviderProps {
  children: ReactNode;
  /** 初始 focused 标的(可选)。 */
  initialSymbol?: string;
}

export function CrosshairProvider({ children, initialSymbol }: CrosshairProviderProps) {
  const stateRef = useRef<CrosshairState>({ ...INITIAL_STATE, symbol: initialSymbol ?? null });
  const listenersRef = useRef(new Set<(s: CrosshairState) => void>());

  const protocol = useMemo<CrosshairProtocol>(
    () => ({
      getState() {
        return stateRef.current;
      },
      broadcast(partial) {
        const next: CrosshairState = { ...stateRef.current, ...partial };
        stateRef.current = next;
        // 通知所有订阅者(同步,不走 setState)
        for (const l of listenersRef.current) {
          try {
            l(next);
          } catch (e) {
            console.error('[CrosshairProvider listener error]', e);
          }
        }
      },
      subscribe(callback): Unsubscribe {
        listenersRef.current.add(callback);
        // 立即推送当前状态
        try {
          callback(stateRef.current);
        } catch (e) {
          console.error('[CrosshairProvider initial push error]', e);
        }
        return () => {
          listenersRef.current.delete(callback);
        };
      },
      clear() {
        const cleared: CrosshairState = {
          symbol: stateRef.current.symbol, // 保留 symbol
          time: null,
          value: null,
          source: null,
        };
        stateRef.current = cleared;
        for (const l of listenersRef.current) {
          try {
            l(cleared);
          } catch (e) {
            console.error('[CrosshairProvider clear error]', e);
          }
        }
      },
    }),
    []
  );

  return <CrosshairContext.Provider value={protocol}>{children}</CrosshairContext.Provider>;
}

CrosshairProvider.displayName = 'CrosshairProvider';

export function useCrosshair(): CrosshairProtocol {
  const ctx = useContext(CrosshairContext);
  if (!ctx) {
    // No-op fallback
    return {
      getState: () => INITIAL_STATE,
      broadcast: () => {},
      subscribe: () => () => {},
      clear: () => {},
    };
  }
  return ctx;
}
